class SelectionHead(nn.Module):
    """Score each record description fragment against the goal."""

    def __init__(self, config: SelectionConfig | None = None) -> None:
        super().__init__()
        self.config = config or SelectionConfig()
        c = self.config
        self.byte_embed = nn.Embedding(c.byte_vocab, c.embed)
        self.goal_proj = nn.Linear(c.embed, c.hidden)
        self.key_proj = nn.Linear(c.embed, c.hidden)
        self.pos_embed = nn.Embedding(c.max_records, c.hidden)
        self.scorer1 = nn.Linear(3 * c.hidden, c.hidden)
        self.scorer2 = nn.Linear(c.hidden, 1)
        self.null_bias = nn.Parameter(torch.zeros(1))

    def encode(self, text: bytes) -> torch.Tensor:
        ids = torch.tensor(list(text), dtype=torch.long)
        return self.byte_embed(ids).mean(0)

    def scores(self, goal: bytes, keys: list[str]) -> torch.Tensor:
        goal_vec = self.goal_proj(self.encode(goal))
        rows = []
        for index, key in enumerate(keys[: self.config.max_records]):
            key_vec = self.key_proj(self.encode(key.encode("utf-8")))
            pos = self.pos_embed(torch.tensor(index, dtype=torch.long))
            rows.append(torch.cat([goal_vec, key_vec, pos]))
        stacked = torch.stack(rows)
        return self.scorer2(torch.tanh(self.scorer1(stacked))).squeeze(-1)

    def forward(self, goal: bytes, keys: list[str]) -> torch.Tensor:
        return self.scores(goal, keys)

def evaluate_reversed(candidate, dev, *, r1: bool, budget: Budget, true_raw: dict) -> dict:
    rows = []
    for fixture in dev:
        generated = generate_one(
            candidate,
            fixture,
            r1=r1,
            records=reversed_records(fixture),
            subject_id=f"cmp-rev-{fixture['index']}",
        )
        scored = score_generation(
            generated["raw_bytes"], fixture["target_bytes"][:-1], generated["terminated"]
        )
        paired = generated["raw_bytes"] == true_raw.get(fixture["index"], b"")
        rows.append(
            {
                "index": fixture["index"],
                "world": fixture["world"],
                "score": scored,
                "paired_with_true": bool(paired),
            }
        )
        budget.ensure(context={"phase": "reversed"})
    accuracy = sum(1 for r in rows if r["score"]["completed"]) / len(rows)
    paired_rate = sum(1 for r in rows if r["paired_with_true"]) / len(rows)
    return {"accuracy": accuracy, "paired_rate": paired_rate, "rows": rows}

def evaluate_source_top1(candidate, dev, *, r1: bool, budget: Budget) -> dict:
    if not r1:
        return {"applicable": False, "reason": "R0 has no span reader to attribute"}
    rows = []
    for fixture in dev:
        gen_state = initial_binding_state(candidate, f"cmp-src-{fixture['index']}")
        prepared = prepare(candidate, gen_state, fixture["goal"].encode(), fixture["records"])
        state, gate_index = observe_goal(candidate, prepared)
        step = answer_step(candidate, prepared, state, EOS, gate_index=gate_index)
        weights = step.read.copy_weights
        offsets = prepared.base.view.record_offsets
        object_index = next(
            (
                index
                for index, record in enumerate(fixture["raw_example"]["records"])
                if record["kind"] == "object"
                and record["description"] == fixture["object_description"]
            ),
            None,
        )
        chosen = int(torch.argmax(weights).item()) if weights.numel() else -1
        chosen_record = None
        for index, (start, end) in enumerate(offsets):
            if start <= chosen < end:
                chosen_record = index
                break
        correct = bool(object_index is not None and chosen_record == object_index)
        rows.append(
            {
                "index": fixture["index"],
                "world": fixture["world"],
                "chosen_record": chosen_record,
                "object_record": object_index,
                "correct": correct,
            }
        )
        budget.ensure(context={"phase": "source_top1"})
    return {"top1": sum(1 for r in rows if r["correct"]) / len(rows), "rows": rows}

def evaluate_reversed(
    candidate, dev, *, arm: str, true_gen: dict, budget: Budget, tag: str
) -> dict:
    rows = []
    for fixture in dev:
        generated = generate(
            candidate,
            fixture,
            arm=arm,
            records=tuple(reversed(fixture["records"])),
            keys=list(reversed(fixture["record_keys"])),
            subject_id=f"{tag}-rev-{fixture['index']}",
        )
        scored = score_generation(
            generated["raw_bytes"], fixture["target_prefix"], generated["terminated"]
        )
        rows.append(
            {
                "index": fixture["index"],
                "world": fixture["world"],
                "score": scored,
                "paired_with_true": generated["raw_bytes"]
                == true_gen.get(fixture["index"], {}).get("raw", b""),
            }
        )
        budget.ensure(context={"phase": "reversed"})
    return {
        "accuracy": sum(1 for row in rows if row["score"]["completed"]) / len(rows),
        "paired_rate": sum(1 for row in rows if row["paired_with_true"]) / len(rows),
        "examples": len(rows),
        "rows": rows,
    }

def evaluate_counterfactual(candidate, dev, *, arm: str, rows, budget: Budget, tag: str) -> dict:
    true_by_index = {row["index"]: row["score"]["completed"] for row in rows}
    out = []
    for fixture in dev:
        swapped = swap_object_name(fixture)
        if swapped is None:
            continue
        generated = generate(
            candidate,
            fixture,
            arm=arm,
            records=swapped["records"],
            subject_id=f"{tag}-map-{fixture['index']}",
        )
        scored = score_generation(
            generated["raw_bytes"], swapped["target_prefix"], generated["terminated"]
        )
        out.append(
            {
                "index": fixture["index"],
                "world": fixture["world"],
                "counterfactual_completed": scored["completed"],
                "true_completed": true_by_index.get(fixture["index"], False),
            }
        )
        budget.ensure(context={"phase": "counterfactual"})
    both = sum(1 for row in out if row["counterfactual_completed"] and row["true_completed"])
    return {
        "applicable": len(out),
        "both_correct": both / len(out) if out else 0.0,
        "rows": out,
    }

def task_checks(entry: dict) -> dict:
    overall = entry["step300"]["overall"]
    return {
        "unseen_output_name": overall["subsets"]["unseen_output_name"] >= GATE_UNSEEN,
        "new_description": overall["subsets"]["new_description"] >= GATE_NEW_DESCRIPTION,
        "overall": overall["completed"] >= GATE_OVERALL,
        "reversed_paired": entry["step300"]["reversed"]["paired_rate"] >= GATE_REVERSED,
    }

def evaluate(candidate, dev, *, arm: str, full: bool, budget: Budget, tag: str) -> tuple[dict, dict]:
    rows = []
    true_gen: dict[int, dict] = {}
    per_example = []
    for fixture in dev:
        trace: list = []
        generated = generate(
            candidate,
            fixture,
            arm=arm,
            trace=trace,
            subject_id=f"{tag}-dev-{fixture['index']}",
        )
        true_gen[fixture["index"]] = {
            "raw": generated["raw_bytes"],
            "terminated": generated["terminated"],
        }
        scored = score_generation(
            generated["raw_bytes"], fixture["target_prefix"], generated["terminated"]
        )
        rows.append(
            {
                "index": fixture["index"],
                "world": fixture["world"],
                "flags": fixture["flags"],
                "score": scored,
            }
        )
        emitted = len(generated["raw_bytes"])
        stats = gamma_row(trace, emitted=min(emitted, len(trace)))
        per_example.append({"index": fixture["index"], **stats})
        budget.ensure(context={"phase": "dev_generate", "index": fixture["index"]})
    out: dict = {
        "overall": summarize(rows),
        "gamma": aggregate_gamma(per_example),
        "selection": selection_report(candidate, dev),
        "examples": len(dev),
    }
    if not full:
        out["rows"] = None
        return out, true_gen

    out["rows"] = rows
    out["reversed"] = evaluate_reversed(
        candidate, dev, arm=arm, true_gen=true_gen, budget=budget, tag=tag
    )
    out["counterfactual"] = evaluate_counterfactual(
        candidate, dev, arm=arm, rows=rows, budget=budget, tag=tag
    )
    out["alpha_reading"] = alpha_reading(candidate, dev)
    out["identity_rescue"] = evaluate_identity_rescue(candidate, dev, budget=budget, tag=tag)
    if ARM_LOCKED[arm]:
        out["content_interventions"] = evaluate_interventions(
            candidate, dev, arm=arm, true_gen=true_gen, budget=budget, tag=tag
        )
    else:
        out["content_interventions"] = {
            "applicable": False,
            "reason": "arm B has no selection lock; content interventions are not defined",
        }
    out["nll"] = evaluate_nll(candidate, dev, arm=arm, budget=budget, tag=tag)
    return out, true_gen

def evaluate_interventions(
    candidate, dev, *, arm: str, true_gen: dict, budget: Budget, tag: str
) -> dict:
    targets = [fixture for fixture in dev if fixture["index"] % 15 == 0]
    rows = []
    for fixture in targets:
        reference = true_gen.get(fixture["index"], {"raw": b"", "terminated": False})
        true_scored = score_generation(
            reference["raw"], fixture["target_prefix"], reference["terminated"]
        )
        no_source = generate(
            candidate,
            fixture,
            arm=arm,
            records=(),
            keys=(),
            subject_id=f"{tag}-int-nosrc-{fixture['index']}",
        )
        alternate = alternate_object_index(fixture)
        if alternate is None:
            continue
        wrong_record = generate(
            candidate,
            fixture,
            arm=arm,
            chosen_record=alternate,
            subject_id=f"{tag}-int-wrec-{fixture['index']}",
        )
        wrong_position = locked_generate_offset0(
            candidate,
            fixture,
            record_index=fixture["selection_label"],
            subject_id=f"{tag}-int-wpos-{fixture['index']}",
        )
        rows.append(
            {
                "index": fixture["index"],
                "world": fixture["world"],
                "true_completed": true_scored["completed"],
                "no_source_completed": score_generation(
                    no_source["raw_bytes"], fixture["target_prefix"], no_source["terminated"]
                )["completed"],
                "wrong_record_completed": score_generation(
                    wrong_record["raw_bytes"], fixture["target_prefix"], wrong_record["terminated"]
                )["completed"],
                "wrong_position_completed": score_generation(
                    wrong_position["raw_bytes"], fixture["target_prefix"], wrong_position["terminated"]
                )["completed"],
            }
        )
        budget.ensure(context={"phase": "content_interventions"})
    true_rate = sum(1 for row in rows if row["true_completed"]) / len(rows)
    drops = {
        name: {
            "completed_rate": sum(1 for row in rows if row[f"{name}_completed"]) / len(rows),
            "drop": true_rate - sum(1 for row in rows if row[f"{name}_completed"]) / len(rows),
        }
        for name in ("no_source", "wrong_record", "wrong_position")
    }
    return {
        "applicable": len(rows),
        "true_completed_rate": true_rate,
        "drops": drops,
        "rows": rows,
    }
